public String fullCountingSort(int[] keys, String[] vals) {
    int n = keys.length;
    List<List<String>> buckets = new ArrayList<>();
    for (int v = 0; v < 100; v++) {
        buckets.add(new ArrayList<>());
    }
    for (int i = 0; i < n; i++) {
        String s = (i < n / 2) ? "-" : vals[i];
        buckets.get(keys[i]).add(s);
    }
    StringBuilder sb = new StringBuilder();
    for (int v = 0; v < 100; v++) {
        for (String s : buckets.get(v)) {
            if (sb.length() > 0) sb.append(' ');
            sb.append(s);
        }
    }
    return sb.toString();
}

