def full_counting_sort(items: list[tuple[int, str]]) -> str:
    n = len(items)
    buckets: list[list[str]] = [[] for _ in range(100)]
    for i, (key, s) in enumerate(items):
        text = '-' if i < n // 2 else s
        buckets[key].append(text)
    out: list[str] = []
    for v in range(100):
        out.extend(buckets[v])
    return ' '.join(out)

