public String fullCountingSortStable(int[] keys, String[] vals) {
    int n = keys.length;
    String[] payload = new String[n];
    for (int i = 0; i < n; i++) {
        payload[i] = (i < n / 2) ? "-" : vals[i];
    }
    int[] count = new int[100];
    for (int k : keys) {
        count[k]++;
    }
    int[] pos = new int[100];
    int running = 0;
    for (int v = 0; v < 100; v++) {
        running += count[v];
        pos[v] = running;
    }
    String[] out = new String[n];
    for (int i = n - 1; i >= 0; i--) {
        out[--pos[keys[i]]] = payload[i];
    }
    return String.join(" ", out);
}

